let canvas=null,texture=null,bitmap=null,active=true,token=null;
function send(message,transfer=[]){parent.postMessage({kind:'life-glfx',token,...message},location.origin,transfer);}
function dispose(){active=false;try{bitmap?.close();texture?.destroy();canvas?._?.texture?.destroy();canvas?._?.spareTexture?.destroy();canvas?._?.gl?.getExtension('WEBGL_lose_context')?.loseContext();}catch{}bitmap=texture=canvas=null;}
addEventListener('pagehide',dispose);addEventListener('unload',dispose);
addEventListener('message',async e=>{if(e.source!==parent||e.origin!==location.origin||token!==null)return;token=e.data.token;try{const {buffer,effect}=e.data;if(!(buffer instanceof ArrayBuffer)||buffer.byteLength>5*1024*1024||!['normal','light','color','sepia','vignette','blur'].includes(effect))throw Error('处理参数无效');if(typeof fx?.canvas!=='function')throw Error('本地效果组件不可用');canvas=fx.canvas();canvas.id='gpu';canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();if(active){send({ok:false,error:'WebGL上下文已丢失，旧下载已清除，请重新生成。'});dispose();}});document.body.append(canvas);const gl=canvas._.gl;bitmap=await createImageBitmap(new Blob([buffer]));if(!active){bitmap.close();return;}if(bitmap.width*bitmap.height>4000000||bitmap.width<1||bitmap.height<1)throw Error('图片像素超过上限');const ratio=Math.min(1,1024/bitmap.width,1024/bitmap.height),w=Math.max(1,Math.floor(bitmap.width*ratio)),h=Math.max(1,Math.floor(bitmap.height*ratio));if(Math.max(w,h)>gl.getParameter(gl.MAX_TEXTURE_SIZE))throw Error('当前设备纹理尺寸不足');const input=document.createElement('canvas');input.width=w;input.height=h;input.getContext('2d').drawImage(bitmap,0,0,w,h);bitmap.close();bitmap=null;texture=canvas.texture(input);canvas.draw(texture);if(effect==='light')canvas.brightnessContrast(.15,.1);if(effect==='color')canvas.hueSaturation(.15,.2);if(effect==='sepia')canvas.sepia(.75);if(effect==='vignette')canvas.vignette(.4,.6);if(effect==='blur')canvas.triangleBlur(5);canvas.update();const copy=document.createElement('canvas');copy.id='photo-effects-result';copy.width=w;copy.height=h;copy.getContext('2d').drawImage(canvas,0,0);const grid=document.createElement('div');grid.style.cssText='display:grid;grid-template-columns:1fr 1fr;gap:8px';for(const [label,picture] of [['原色参考',input],['效果预览',copy]]){const box=document.createElement('section'),title=document.createElement('p');title.textContent=label;box.append(title,picture);grid.append(box);}document.body.append(grid);texture.destroy();texture=null;copy.toBlob(async blob=>{try{if(!active)return;if(!blob)throw Error('PNG编码失败，请重试。');const bytes=await blob.arrayBuffer();if(active)send({ok:true,buffer:bytes,width:w,height:h},[bytes]);}catch(e){if(active)send({ok:false,error:'PNG编码或读取失败，请重试。'});dispose();}},'image/png');}catch(e){send({ok:false,error:typeof e==='string'?e:e.message||'效果处理失败'});dispose();}});
